import React, { useState } from 'react';
import EvidenceLocker from './EvidenceLocker';
import { polishDescription } from '../utils/polish';
import { api } from '../utils/api';

const CATEGORIES = [
  'Cyberbullying',
  'Stalking',
  'Threats',
  'Impersonation',
  'Campus/Workplace Sexual Harassment',
];

const initialState = {
  category: '',
  description: '',
  handles: '',
  urls: '',
  phone: '',
};

export default function ReportForm({ onSubmitted, voiceTranscript }) {
  const [form, setForm] = useState(initialState);
  const [polished, setPolished] = useState('');
  const [evidence, setEvidence] = useState([]);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState('');

  // Live-append hands-free dictated speech into the description field.
  React.useEffect(() => {
    if (voiceTranscript) {
      setForm((f) => ({ ...f, description: voiceTranscript }));
    }
  }, [voiceTranscript]);

  const update = (key) => (e) => setForm((f) => ({ ...f, [key]: e.target.value }));

  const handlePolish = () => {
    if (!form.description.trim()) return;
    const result = polishDescription(form.description, {
      category: form.category,
      suspectIdentifiers: { handles: form.handles, urls: form.urls, phone: form.phone },
    });
    setPolished(result);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!form.category) return setError('Please select a category.');
    if (!form.description.trim()) return setError('Please describe what happened.');

    setSubmitting(true);
    try {
      const { case: created, token } = await api.createCase({
        category: form.category,
        description: form.description,
        polishedDescription: polished || null,
        suspectIdentifiers: { handles: form.handles, urls: form.urls, phone: form.phone },
        evidence,
      });
      onSubmitted(created || { token });
      setForm(initialState);
      setPolished('');
      setEvidence([]);
    } catch (err) {
      setError(err.message);
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <form className="report-form card" onSubmit={handleSubmit}>
      <h2>Guided Incident Report</h2>
      <p className="muted">Take your time. Nothing is submitted until you choose to send it.</p>

      <div className="field">
        <label className="field-label" htmlFor="category">Category</label>
        <select id="category" value={form.category} onChange={update('category')} required>
          <option value="" disabled>Select a category…</option>
          {CATEGORIES.map((c) => <option key={c} value={c}>{c}</option>)}
        </select>
      </div>

      <div className="field">
        <label className="field-label" htmlFor="description">What happened?</label>
        <textarea
          id="description"
          rows={6}
          placeholder="Describe the incident in your own words, in as much or as little detail as feels okay…"
          value={form.description}
          onChange={update('description')}
        />
        <button type="button" className="btn btn-accent btn-sm ai-polish-btn" onClick={handlePolish}>
          ✨ AI Auto-Polish Description
        </button>
        {polished && (
          <div className="polished-preview">
            <label className="field-label">Law-enforcement-ready summary (attached to your report)</label>
            <pre>{polished}</pre>
          </div>
        )}
      </div>

      <fieldset className="field">
        <legend className="field-label">Suspect identifiers (optional)</legend>
        <input placeholder="Handles / usernames" value={form.handles} onChange={update('handles')} />
        <input placeholder="URLs / profile links" value={form.urls} onChange={update('urls')} />
        <input placeholder="Phone number" value={form.phone} onChange={update('phone')} />
      </fieldset>

      <EvidenceLocker evidence={evidence} setEvidence={setEvidence} />

      {error && <p className="form-error">{error}</p>}

      <button type="submit" className="btn btn-primary btn-block" disabled={submitting}>
        {submitting ? 'Securing report…' : 'Submit Anonymous Report'}
      </button>
    </form>
  );
}
